def finiteDualCoefficients (D : ConstructionData 𝕜) (E : Interval)
    (φ : PreSpace D →L[𝕜] 𝕜) : C00 𝕜 :=
  ∑ n ∈ E.set, Finsupp.single n (φ (PreSpace.single n 1))

